        "tool_json": {
            "type": "function",
            "function": {
                "name": tool_settings.name,
                "description": tool_settings.description,
                "parameters": {
                    "type": "object",
                    "properties": tool_settings.parameters or {},
                    "required": [
                        k for k, v in (tool_settings.parameters or {}).items()
                        if v.get("required", False)
                    ],
                }
            }
        },
        "settings": ToolSettings(scope="chat").dict(),
        "tags": ["browser", "automation", "web-interaction"],
        "tool_call": None,  # Will be set based on tool name
    }

    # Map tool names to functions
    if tool_settings.name == "start_session":
        tool_entry["tool_call"] = start_session
    elif tool_settings.name == "browse_action":
        tool_entry["tool_call"] = browse_action
    elif tool_settings.name == "get_screenshot":
        tool_entry["tool_call"] = get_screenshot
    elif tool_settings.name == "get_source_code":
        tool_entry["tool_call"] = get_source_code
    elif tool_settings.name == "finish_session":
        tool_entry["tool_call"] = finish_session

    TOOLS.append(tool_entry)

